package com.devteciot.dev_erp.Controller; import com.devteciot.dev_erp.DTO.DTOSetor.*; import com.devteciot.dev_erp.Service.SetorService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/setores") @RequiredArgsConstructor public class SetorController {private final SetorService s; @GetMapping public List<SetorGetDTO> listar(){return s.listar();}@GetMapping("/{id}") public SetorGetDTO buscar(@PathVariable Long id){return s.buscar(id);}@PostMapping public ResponseEntity<SetorGetDTO> criar(@Valid @RequestBody SetorPostDTO d){return ResponseEntity.status(HttpStatus.CREATED).body(s.criar(d));}@PutMapping("/{id}") public SetorGetDTO atualizar(@PathVariable Long id,@Valid @RequestBody SetorPostDTO d){return s.atualizar(id,d);}@DeleteMapping("/{id}") public ResponseEntity<Void> excluir(@PathVariable Long id){s.excluir(id);return ResponseEntity.noContent().build();}}
